/**
 * Programmatic technical workflow generated by customer-churn-reference@1.
 * Kept structurally typed so @anvil/system3 does not import the generic engine.
 */
export function buildUnderstandProjectWorkflow(input: {
  projectId: string;
  inputSnapshotId: string;
  sources: readonly {
    id: string;
    kind: string;
    filename: string;
    mediaType: string;
    contentHash: string;
  }[];
}): {
  name: string;
  description: string;
  provider: string;
  worktree: { enabled: boolean };
  mutates_checkout: boolean;
  output_schema: Record<string, unknown>;
  outputs: Record<string, string>;
  nodes: Record<string, unknown>[];
} {
  return {
    name: 'system3-understand-project',
    description: 'Verify immutable inputs and build an inspectable Project Understanding snapshot',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    output_schema: {
      type: 'object',
      properties: {
        analysis: { type: 'object' },
        reports: { type: 'array' },
        semanticAssistance: { type: ['object', 'null'] },
      },
      required: ['analysis', 'reports', 'semanticAssistance'],
    },
    outputs: {
      analysis: '$analyze-understanding.output.analysis',
      reports: '$analyze-understanding.output.reports',
      semanticAssistance: '$analyze-understanding.output.semanticAssistance',
    },
    nodes: [
      {
        id: 'verify-input-snapshot',
        action: {
          executor: 'system3.input-snapshot-verifier',
          input: {
            projectId: input.projectId,
            inputSnapshotId: input.inputSnapshotId,
            sources: input.sources,
          },
        },
        timeout: 30_000,
        output_type: 'system3-input-snapshot',
      },
      {
        id: 'analyze-understanding',
        depends_on: ['verify-input-snapshot'],
        action: {
          executor: 'system3.understanding-analyzer',
          input: {
            projectId: input.projectId,
            inputSnapshotId: input.inputSnapshotId,
            sources: '$verify-input-snapshot.output.sources',
          },
        },
        timeout: 120_000,
        output_type: 'system3-project-understanding',
      },
    ],
  };
}

export function buildReadinessContractWorkflow(input: {
  analysis: unknown;
  decisions: readonly { id: string; status: 'pending' | 'answered'; answer: string | null }[];
  knowledgeSnapshotId: string;
  projectVersion: number;
  datasetSourceVersionId: string | null;
  requiredCapabilityIds: readonly string[];
  availableCapabilityIds: readonly string[];
}): {
  name: string;
  description: string;
  provider: string;
  worktree: { enabled: boolean };
  mutates_checkout: boolean;
  output_schema: Record<string, unknown>;
  outputs: Record<string, string>;
  nodes: Record<string, unknown>[];
} {
  return {
    name: 'system3-readiness-contract',
    description: 'Evaluate explicit gates and freeze the approved readiness contract',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    output_schema: {
      type: 'object',
      properties: {
        evaluation: { type: 'object' },
        contract: { type: ['object', 'null'] },
      },
      required: ['evaluation', 'contract'],
    },
    outputs: {
      evaluation: '$finalize-contract.output.evaluation',
      contract: '$finalize-contract.output.contract',
    },
    nodes: [
      {
        id: 'evaluate-gates',
        action: {
          executor: 'system3.readiness-gate-evaluator',
          input: {
            analysis: input.analysis,
            pendingDecisionCount: input.decisions.filter(decision => decision.status === 'pending')
              .length,
            knowledgeSnapshotId: input.knowledgeSnapshotId,
            projectVersion: input.projectVersion,
            datasetSourceVersionId: input.datasetSourceVersionId,
            requiredCapabilityIds: input.requiredCapabilityIds,
            availableCapabilityIds: input.availableCapabilityIds,
          },
        },
        timeout: 10_000,
        output_type: 'system3-readiness-gates',
      },
      {
        id: 'resolve-decisions',
        action: {
          executor: 'system3.decision-resolver',
          input: { decisions: input.decisions },
        },
        timeout: 10_000,
        output_type: 'system3-resolved-decisions',
      },
      {
        id: 'finalize-contract',
        depends_on: ['evaluate-gates', 'resolve-decisions'],
        action: {
          executor: 'system3.readiness-contract-builder',
          input: {
            analysis: input.analysis,
            evaluation: '$evaluate-gates.output.evaluation',
            datasetSourceVersionId: input.datasetSourceVersionId,
            resolvedDecisions: '$resolve-decisions.output.resolvedDecisions',
          },
        },
        timeout: 10_000,
        output_type: 'system3-readiness-contract',
      },
    ],
  };
}

interface TechnicalWorkflow {
  name: string;
  description: string;
  provider: string;
  worktree: { enabled: boolean };
  mutates_checkout: boolean;
  input_schema?: Record<string, unknown>;
  output_schema?: Record<string, unknown>;
  outputs?: Record<string, string>;
  nodes: Record<string, unknown>[];
}

/**
 * Immutable execution bundle for an approved Customer Churn MVP plan.
 * Child workflows exchange typed paths/results. Scoped runs materialize one
 * content-addressed approved package rather than copying another run's root.
 */
export function buildCustomerChurnExecutionWorkflows(input: {
  projectId: string;
  executionId: string;
  compilationId: string;
  definitionHash: string;
  projectName: string;
  targetColumn: string;
  datasetSource: {
    id: string;
    contentHash: string;
  };
  plan: Record<string, unknown>;
  analysis: unknown;
  rerunScope: {
    executionMode: 'full' | 'experiment' | 'delivery';
    reusedArtifacts: readonly {
      kind: 'delivery_package';
      storageKey: string;
      contentHash: string;
      sourceExecutionId: string;
    }[];
  };
}): { root: TechnicalWorkflow; definitions: TechnicalWorkflow[] } {
  const common = {
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
  } as const;
  const build: TechnicalWorkflow = {
    ...common,
    name: 'system3-baseline-build',
    description: 'Materialize the approved plan and generate a deterministic Python baseline',
    output_schema: {
      type: 'object',
      properties: { projectDir: { type: 'string' } },
      required: ['projectDir'],
    },
    outputs: { projectDir: '$validate-project.output.projectDir' },
    nodes: [
      {
        id: 'materialize-approved-plan',
        action: {
          executor: 'system3.approved-plan-materializer',
          input: {
            projectId: input.projectId,
            compilationId: input.compilationId,
            definitionHash: input.definitionHash,
            plan: input.plan,
          },
        },
        timeout: 10_000,
        output_type: 'system3-approved-plan',
      },
      {
        id: 'scaffold-project',
        depends_on: ['materialize-approved-plan'],
        action: {
          executor: 'system3.project-scaffolder',
          input: {
            projectId: input.projectId,
            projectName: input.projectName,
            targetColumn: input.targetColumn,
            datasetSourceVersionId: input.datasetSource.id,
            datasetContentHash: input.datasetSource.contentHash,
          },
        },
        timeout: 30_000,
        output_type: 'system3-generated-project',
      },
      {
        id: 'validate-project',
        depends_on: ['scaffold-project'],
        action: {
          executor: 'system3.project-validator',
          input: { projectDir: '$scaffold-project.output.projectDir' },
        },
        timeout: 10_000,
        output_type: 'system3-project-validation',
      },
    ],
  };
  const experiment: TechnicalWorkflow = {
    ...common,
    name: 'system3-baseline-experiment',
    description: 'Validate data, run tests and execute the deterministic majority baseline',
    input_schema: {
      type: 'object',
      properties: { projectDir: { type: 'string' } },
      required: ['projectDir'],
    },
    output_schema: {
      type: 'object',
      properties: {
        projectDir: { type: 'string' },
        testResult: { type: 'object' },
        dataResult: { type: 'object' },
        experiment: { type: 'object' },
        packagePath: { type: 'string' },
      },
      required: ['projectDir', 'testResult', 'dataResult', 'experiment', 'packagePath'],
    },
    outputs: {
      projectDir: '$run-baseline.output.projectDir',
      testResult: '$run-tests.output.testResult',
      dataResult: '$run-data-pipeline.output.dataResult',
      experiment: '$run-baseline.output.experiment',
      packagePath: '$persist-baseline-artifacts.output.packagePath',
    },
    nodes: [
      {
        id: 'validate-dataset',
        action: {
          executor: 'system3.dataset-validator',
          input: { projectDir: '$INPUTS.projectDir' },
        },
        timeout: 10_000,
        output_type: 'system3-dataset-validation',
      },
      {
        id: 'run-tests',
        depends_on: ['validate-dataset'],
        action: {
          executor: 'system3.test-runner',
          input: { projectDir: '$validate-dataset.output.projectDir' },
        },
        timeout: 120_000,
        output_type: 'system3-test-results',
      },
      {
        id: 'run-data-pipeline',
        depends_on: ['run-tests'],
        action: {
          executor: 'system3.data-pipeline-runner',
          input: { projectDir: '$run-tests.output.projectDir' },
        },
        timeout: 120_000,
        output_type: 'system3-data-run',
      },
      {
        id: 'run-baseline',
        depends_on: ['run-data-pipeline'],
        action: {
          executor: 'system3.baseline-runner',
          input: { projectDir: '$run-data-pipeline.output.projectDir' },
        },
        timeout: 120_000,
        output_type: 'system3-baseline-result',
      },
      {
        id: 'persist-baseline-artifacts',
        depends_on: ['run-baseline'],
        action: {
          executor: 'system3.baseline-artifact-packager',
          input: { projectDir: '$run-baseline.output.projectDir' },
        },
        timeout: 120_000,
        output_type: 'system3-baseline-artifact',
      },
    ],
  };
  const reusedArtifact = input.rerunScope.reusedArtifacts[0];
  if (input.rerunScope.executionMode !== 'full' && reusedArtifact === undefined) {
    throw new Error(
      `Scoped ${input.rerunScope.executionMode} execution requires a reusable artifact`
    );
  }
  const reuse: TechnicalWorkflow = {
    ...common,
    name: 'system3-reuse-approved-delivery',
    description: 'Verify and materialize the exact approved delivery artifact for a scoped rerun',
    output_schema: {
      type: 'object',
      properties: {
        projectDir: { type: 'string' },
        testResult: { type: 'object' },
        dataResult: { type: 'object' },
        experiment: { type: 'object' },
        packagePath: { type: 'string' },
        reusedArtifact: { type: 'object' },
      },
      required: [
        'projectDir',
        'testResult',
        'dataResult',
        'experiment',
        'packagePath',
        'reusedArtifact',
      ],
    },
    outputs: {
      projectDir: '$materialize-approved-artifact.output.projectDir',
      testResult: '$materialize-approved-artifact.output.testResult',
      dataResult: '$materialize-approved-artifact.output.dataResult',
      experiment: '$materialize-approved-artifact.output.experiment',
      packagePath: '$materialize-approved-artifact.output.packagePath',
      reusedArtifact: '$materialize-approved-artifact.output.reusedArtifact',
    },
    nodes: [
      {
        id: 'materialize-approved-artifact',
        action: {
          executor: 'system3.delivery-artifact-materializer',
          input: {
            projectId: input.projectId,
            storageKey: reusedArtifact?.storageKey,
            contentHash: reusedArtifact?.contentHash,
            sourceExecutionId: reusedArtifact?.sourceExecutionId,
          },
        },
        timeout: 120_000,
        output_type: 'system3-reused-delivery-artifact',
      },
    ],
  };
  const fullNodes: Record<string, unknown>[] = [
    { id: 'baseline-build', workflow: { name: build.name } },
    {
      id: 'baseline-experiment',
      depends_on: ['baseline-build'],
      workflow: {
        name: experiment.name,
        inputs: { projectDir: '$baseline-build.output.projectDir' },
      },
    },
  ];
  const experimentNodes: Record<string, unknown>[] = [
    { id: 'reuse-build-artifact', workflow: { name: reuse.name } },
    {
      id: 'materialize-pinned-dataset',
      depends_on: ['reuse-build-artifact'],
      action: {
        executor: 'system3.pinned-dataset-materializer',
        input: {
          projectId: input.projectId,
          projectDir: '$reuse-build-artifact.output.projectDir',
          targetColumn: input.targetColumn,
          datasetSourceVersionId: input.datasetSource.id,
          datasetContentHash: input.datasetSource.contentHash,
        },
      },
      timeout: 10_000,
      output_type: 'system3-pinned-dataset',
    },
    {
      id: 'baseline-experiment',
      depends_on: ['materialize-pinned-dataset'],
      workflow: {
        name: experiment.name,
        inputs: { projectDir: '$materialize-pinned-dataset.output.projectDir' },
      },
    },
  ];
  const deliveryNodes: Record<string, unknown>[] = [
    { id: 'reuse-experiment-artifact', workflow: { name: reuse.name } },
  ];
  const root: TechnicalWorkflow = {
    ...common,
    name: 'system3-customer-churn-execution',
    description: 'Approved Customer Churn MVP baseline execution with immutable child snapshots',
    output_schema: {
      type: 'object',
      properties: {
        projectDir: { type: 'string' },
        testResult: { type: 'object' },
        dataResult: { type: 'object' },
        experiment: { type: 'object' },
        packagePath: { type: 'string' },
      },
      required: ['projectDir', 'testResult', 'dataResult', 'experiment'],
    },
    outputs:
      input.rerunScope.executionMode === 'full' || input.rerunScope.executionMode === 'experiment'
        ? {
            projectDir: '$baseline-experiment.output.projectDir',
            testResult: '$baseline-experiment.output.testResult',
            dataResult: '$baseline-experiment.output.dataResult',
            experiment: '$baseline-experiment.output.experiment',
            packagePath: '$baseline-experiment.output.packagePath',
          }
        : {
            projectDir: '$reuse-experiment-artifact.output.projectDir',
            testResult: '$reuse-experiment-artifact.output.testResult',
            dataResult: '$reuse-experiment-artifact.output.dataResult',
            experiment: '$reuse-experiment-artifact.output.experiment',
            packagePath: '$reuse-experiment-artifact.output.packagePath',
          },
    nodes:
      input.rerunScope.executionMode === 'full'
        ? fullNodes
        : input.rerunScope.executionMode === 'experiment'
          ? experimentNodes
          : deliveryNodes,
  };
  const definitions =
    input.rerunScope.executionMode === 'full'
      ? [root, build, experiment]
      : input.rerunScope.executionMode === 'experiment'
        ? [root, reuse, experiment]
        : [root, reuse];
  return { root, definitions };
}

interface ImmutableBaselineArtifact {
  storageKey: string;
  contentHash: string;
  sourceExecutionId: string;
}

function buildBaselineReuseWorkflow(input: {
  projectId: string;
  artifact: ImmutableBaselineArtifact;
}): TechnicalWorkflow {
  return {
    name: 'system3-materialize-baseline-artifact',
    description: 'Verify and materialize an immutable baseline artifact',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    output_schema: {
      type: 'object',
      properties: {
        projectDir: { type: 'string' },
        testResult: { type: 'object' },
        dataResult: { type: 'object' },
        experiment: { type: 'object' },
        packagePath: { type: 'string' },
      },
      required: ['projectDir', 'testResult', 'dataResult', 'experiment', 'packagePath'],
    },
    outputs: {
      projectDir: '$materialize.output.projectDir',
      testResult: '$materialize.output.testResult',
      dataResult: '$materialize.output.dataResult',
      experiment: '$materialize.output.experiment',
      packagePath: '$materialize.output.packagePath',
    },
    nodes: [
      {
        id: 'materialize',
        action: {
          executor: 'system3.delivery-artifact-materializer',
          input: {
            projectId: input.projectId,
            storageKey: input.artifact.storageKey,
            contentHash: input.artifact.contentHash,
            sourceExecutionId: input.artifact.sourceExecutionId,
          },
        },
        timeout: 120_000,
        output_type: 'system3-materialized-baseline',
      },
    ],
  };
}

export function buildCustomerChurnVerificationWorkflows(input: {
  projectId: string;
  analysis: unknown;
  artifact: ImmutableBaselineArtifact;
}): { root: TechnicalWorkflow; definitions: TechnicalWorkflow[] } {
  const reuse = buildBaselineReuseWorkflow(input);
  const verify: TechnicalWorkflow = {
    name: 'system3-verify',
    description: 'Validate baseline artifacts and build honest requirement evidence',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    input_schema: reuse.output_schema,
    output_schema: {
      type: 'object',
      properties: { evidenceMap: { type: 'object' }, gate: { type: 'object' } },
      required: ['evidenceMap', 'gate'],
    },
    outputs: {
      evidenceMap: '$build-evidence-map.output.evidenceMap',
      gate: '$evaluate-baseline-gate.output.gate',
    },
    nodes: [
      {
        id: 'validate-artifact-schemas',
        action: {
          executor: 'system3.artifact-schema-validator',
          input: {
            projectDir: '$INPUTS.projectDir',
            analysis: input.analysis,
            testResult: '$INPUTS.testResult',
            dataResult: '$INPUTS.dataResult',
            experiment: '$INPUTS.experiment',
          },
        },
        timeout: 10_000,
        output_type: 'system3-artifact-validation',
      },
      {
        id: 'build-evidence-map',
        depends_on: ['validate-artifact-schemas'],
        action: {
          executor: 'system3.evidence-map-builder',
          input: {
            projectDir: '$INPUTS.projectDir',
            analysis: input.analysis,
            testResult: '$INPUTS.testResult',
            dataResult: '$INPUTS.dataResult',
            experiment: '$INPUTS.experiment',
          },
        },
        timeout: 10_000,
        output_type: 'system3-evidence-map',
      },
      {
        id: 'evaluate-baseline-gate',
        depends_on: ['build-evidence-map'],
        action: {
          executor: 'system3.baseline-gate-evaluator',
          input: { evidenceMap: '$build-evidence-map.output.evidenceMap' },
        },
        timeout: 10_000,
        output_type: 'system3-baseline-gate',
      },
    ],
  };
  const root: TechnicalWorkflow = {
    name: 'system3-customer-churn-verification',
    description: 'Independent verification of one immutable baseline execution artifact',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    output_schema: verify.output_schema,
    outputs: {
      evidenceMap: '$verify.output.evidenceMap',
      gate: '$verify.output.gate',
    },
    nodes: [
      { id: 'materialize-baseline', workflow: { name: reuse.name } },
      {
        id: 'verify',
        depends_on: ['materialize-baseline'],
        workflow: {
          name: verify.name,
          inputs: {
            projectDir: '$materialize-baseline.output.projectDir',
            testResult: '$materialize-baseline.output.testResult',
            dataResult: '$materialize-baseline.output.dataResult',
            experiment: '$materialize-baseline.output.experiment',
            packagePath: '$materialize-baseline.output.packagePath',
          },
        },
      },
    ],
  };
  return { root, definitions: [root, reuse, verify] };
}

export function buildCustomerChurnDeliveryWorkflows(input: {
  projectId: string;
  executionId: string;
  artifact: ImmutableBaselineArtifact;
  evidenceMap: Record<string, unknown>;
  gate: Record<string, unknown>;
}): { root: TechnicalWorkflow; definitions: TechnicalWorkflow[] } {
  const reuse = buildBaselineReuseWorkflow(input);
  const delivery: TechnicalWorkflow = {
    name: 'system3-delivery',
    description: 'Package verified artifacts and produce an immutable delivery manifest',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    input_schema: {
      type: 'object',
      properties: { projectDir: { type: 'string' } },
      required: ['projectDir'],
    },
    output_schema: {
      type: 'object',
      properties: { delivery: { type: 'object' } },
      required: ['delivery'],
    },
    outputs: { delivery: '$delivery-manifest.output.delivery' },
    nodes: [
      {
        id: 'package',
        action: {
          executor: 'system3.delivery-packager',
          input: { projectDir: '$INPUTS.projectDir', gate: input.gate },
        },
        timeout: 120_000,
        output_type: 'system3-delivery-package',
      },
      {
        id: 'delivery-manifest',
        depends_on: ['package'],
        action: {
          executor: 'system3.delivery-manifest-builder',
          input: {
            projectId: input.projectId,
            executionId: input.executionId,
            packagePath: '$package.output.packagePath',
            evidenceMap: input.evidenceMap,
            gate: input.gate,
          },
        },
        timeout: 10_000,
        output_type: 'system3-delivery-manifest',
      },
    ],
  };
  const root: TechnicalWorkflow = {
    name: 'system3-customer-churn-delivery',
    description: 'Manual delivery from a current successful verification',
    provider: 'claude',
    worktree: { enabled: false },
    mutates_checkout: false,
    output_schema: delivery.output_schema,
    outputs: { delivery: '$delivery.output.delivery' },
    nodes: [
      { id: 'materialize-baseline', workflow: { name: reuse.name } },
      {
        id: 'delivery',
        depends_on: ['materialize-baseline'],
        workflow: {
          name: delivery.name,
          inputs: { projectDir: '$materialize-baseline.output.projectDir' },
        },
      },
    ],
  };
  return { root, definitions: [root, reuse, delivery] };
}
